class NaiveTicTacToe {
    private final int[][] board;
    private final int n;
    public NaiveTicTacToe(int n) { this.n = n; this.board = new int[n][n]; }
    public int move(int r, int c, int player) {
        board[r][c] = player;
        // row
        boolean win = true;
        for (int j = 0; j < n; j++) if (board[r][j] != player) { win = false; break; }
        if (win) return player;
        // col
        win = true;
        for (int i = 0; i < n; i++) if (board[i][c] != player) { win = false; break; }
        if (win) return player;
        // diag
        if (r == c) {
            win = true;
            for (int i = 0; i < n; i++) if (board[i][i] != player) { win = false; break; }
            if (win) return player;
        }
        if (r + c == n - 1) {
            win = true;
            for (int i = 0; i < n; i++) if (board[i][n - 1 - i] != player) { win = false; break; }
            if (win) return player;
        }
        return 0;
    }
}

