enum Mark { EMPTY, X, O }
enum GameState { IN_PROGRESS, WON, DRAW }

class Board {
    final int n;
    private final Mark[][] grid;
    private int moves;
    Board(int n) { this.n = n; grid = new Mark[n][n];
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) grid[i][j] = Mark.EMPTY; }
    boolean isEmpty(int r, int c) { return grid[r][c] == Mark.EMPTY; }
    void place(int r, int c, Mark m) { grid[r][c] = m; moves++; }
    void clear(int r, int c) { grid[r][c] = Mark.EMPTY; moves--; }
    boolean isFull() { return moves == n * n; }
    boolean inBounds(int r, int c) { return r >= 0 && r < n && c >= 0 && c < n; }
}

/** O(1) n-in-a-row detector. Dual counters: clearer undo than +1/-1 trick. */
class CounterWinStrategy {
    private final int n;
    private final int[] rowsX, rowsO, colsX, colsO;
    private int diagX, diagO, antiX, antiO;
    CounterWinStrategy(int n) { this.n = n;
        rowsX = new int[n]; rowsO = new int[n]; colsX = new int[n]; colsO = new int[n]; }
    boolean record(int r, int c, Mark m) {
        if (m == Mark.X) {
            if (++rowsX[r] == n || ++colsX[c] == n) return true;
            if (r == c && ++diagX == n) return true;
            if (r + c == n - 1 && ++antiX == n) return true;
        } else {
            if (++rowsO[r] == n || ++colsO[c] == n) return true;
            if (r == c && ++diagO == n) return true;
            if (r + c == n - 1 && ++antiO == n) return true;
        }
        return false;
    }
    void revert(int r, int c, Mark m) {
        if (m == Mark.X) { rowsX[r]--; colsX[c]--; if (r == c) diagX--; if (r + c == n - 1) antiX--; }
        else { rowsO[r]--; colsO[c]--; if (r == c) diagO--; if (r + c == n - 1) antiO--; }
    }
}

public class TicTacToe {
    private final Board board;
    private final CounterWinStrategy win;
    private Mark current = Mark.X;
    private GameState state = GameState.IN_PROGRESS;
    private final java.util.ArrayDeque<int[]> history = new java.util.ArrayDeque<>();
    public TicTacToe(int n) { if (n <= 0) throw new IllegalArgumentException("n>0");
        board = new Board(n); win = new CounterWinStrategy(n); }
    /** LLD-style: turn owned internally. Returns 1/2 on win, 0 otherwise. */
    public synchronized int move(int r, int c) {
        if (state != GameState.IN_PROGRESS) throw new IllegalStateException("game over: " + state);
        if (!board.inBounds(r, c)) throw new IllegalArgumentException("out of bounds");
        if (!board.isEmpty(r, c)) throw new IllegalArgumentException("cell occupied");
        board.place(r, c, current);
        history.push(new int[]{r, c});
        boolean won = win.record(r, c, current);
        Mark played = current;
        if (won) state = GameState.WON;
        else if (board.isFull()) state = GameState.DRAW;
        else current = (current == Mark.X ? Mark.O : Mark.X);
        return won ? (played == Mark.X ? 1 : 2) : 0;
    }
    public synchronized void undo() {
        if (history.isEmpty()) throw new IllegalStateException("nothing to undo");
        int[] last = history.pop();
        // If game was won by the last move, current still points at winner; else it points at next player.
        Mark lastMark = (state == GameState.WON) ? current : (current == Mark.X ? Mark.O : Mark.X);
        board.clear(last[0], last[1]);
        win.revert(last[0], last[1], lastMark);
        current = lastMark;
        state = GameState.IN_PROGRESS;
    }
    public GameState getState() { return state; }
}
